def run(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True)

def jest(test):
    for intento in (1, 2):
        r = run(f"bunx jest --testTimeout=30000 --runTestsByPath {test} 2>&1")
        if 'Exceeded timeout' not in r.stdout: return r.stdout
        print(f"    timeout en el intento {intento}; se repite", flush=True)
    return r.stdout

ok = True
for g in sys.argv[1:]:
    for k, (f, reps) in G[g].items():
        if run(f"git diff --quiet HEAD -- {f}").returncode != 0:
            print(f"PARA: {f} no está igual que HEAD antes de {k}"); sys.exit(2)
        s = open(f).read()
        for a, b in reps:
            if s.count(a) != 1:
                print(f"PARA: el ancla de {k} sale {s.count(a)} veces en {f}"); sys.exit(2)
            s = s.replace(a, b)
        open(f, 'w').write(s)
        try:
            out = jest(T[f])
        finally:
            run(f"git checkout HEAD -- {f}")
        if run(f"git diff --quiet HEAD -- {f}").returncode != 0:
            print(f"PARA: {f} no volvió a HEAD tras {k}"); sys.exit(2)
        reds = [l.strip()[2:].strip() for l in out.splitlines() if l.strip().startswith('●') and 'Console' not in l]
        want = EXPECTED[k]
        tests = re.search(r'Tests:.*', out)
        good = sorted(reds) == sorted(want) and 'Exceeded timeout' not in out
        ok &= good
        print(f"{'OK ' if good else 'MAL'} {g} {k}: {len(reds)} rojos (esperados {len(want)}) | {tests.group(0) if tests else 'sin línea Tests'}", flush=True)
        if not good:
            for x in sorted(set(want) - set(reds)): print(f"    falta: {x}")
            for x in sorted(set(reds) - set(want)): print(f"    sobra: {x}")
sys.exit(0 if ok else 1)
